 /** Message keys per language, for checks. */
 export const messageKeys = (lang) => Object.keys(MESSAGES[lang] ?? {});
+
+/** Picks "ko" or "en" from an Accept-Language header value (q-values, region tags), else `fallback`. */
+export function pickLanguage(header, fallback = "en") {
+  let best = null;
+  let bestQ = 0;
+  String(header ?? "").split(",").forEach((part) => {
+    const [tag, ...params] = part.trim().split(";");
+    const lang = tag.trim().toLowerCase().split("-")[0];
+    if (!LANGUAGES.includes(lang)) return;
+    const qParam = params.map((p) => p.trim()).find((p) => /^q=/i.test(p));
+    const q = qParam === undefined ? 1 : Number(qParam.slice(2));
+    if (Number.isFinite(q) && q > bestQ) {
+      best = lang;
+      bestQ = q;
+    }
+  });
+  return best ?? fallback;
+}
